// Tool schemas - defines parameters for each MCP tool
const toolSchemas = {
  "video-transcription": {
    description: "Transcribe audio/video files using OpenAI Whisper",
    parameters: {
      required: {
        url: { type: "string", description: "URL of the audio/video file to transcribe" }
      },
      optional: {
        language: { type: "string", description: "Language code (e.g., 'en', 'fr')", default: "auto-detect" },
        execution_mode: { type: "string", enum: ["online", "offline"], default: "online" }
      }
    }
  },
  "text-to-speech": {
    description: "Convert text to speech using OpenAI TTS",
    parameters: {
      required: {
        text: { type: "string", description: "Text to convert to speech" }
      },
      optional: {
        voice: { type: "string", enum: ["alloy", "echo", "fable", "onyx", "nova", "shimmer"], default: "alloy" },
        model: { type: "string", enum: ["tts-1", "tts-1-hd"], default: "tts-1" },
        speed: { type: "number", minimum: 0.25, maximum: 4.0, default: 1.0 },
        execution_mode: { type: "string", enum: ["online", "offline"], default: "online" }
      }
    }
  },
  "linkedin": {
    description: "Interact with LinkedIn profiles and posts",
    parameters: {
      required: {
        action: { type: "string", enum: ["get_profile", "search"], description: "Action to perform" }
      },
      optional: {
        profile_url: { type: "string", description: "LinkedIn profile URL (for get_profile)" },
        query: { type: "string", description: "Search query (for search action)" },
        execution_mode: { type: "string", enum: ["online", "offline"], default: "online" }
      }
    }
  },
  "pdf-extractor": {
    description: "Extract text content from PDF files",
    parameters: {
      required: {
        url: { type: "string", description: "URL of the PDF file to extract" }
      },
      optional: {
        pages: { type: "string", description: "Page range (e.g., '1-5', 'all')", default: "all" },
        execution_mode: { type: "string", enum: ["online", "offline"], default: "online" }
      }
    }
  },
  "entity-extractor": {
    description: "Extract named entities from text using OpenAI",
    parameters: {
      required: {
        text: { type: "string", description: "Text to analyze for entities" }
      },
      optional: {
        entity_types: { type: "array", items: "string", description: "Types to extract", default: ["PERSON", "ORGANIZATION", "LOCATION", "DATE"] },
        execution_mode: { type: "string", enum: ["online", "offline"], default: "online" }
      }
    }
  },
  "summarizer": {
    description: "Summarize text using Anthropic Claude",
    parameters: {
      required: {
        text: { type: "string", description: "Text to summarize" }
      },
      optional: {
        style: { type: "string", enum: ["concise", "detailed", "bullet-points"], default: "concise" },
        max_length: { type: "integer", description: "Max length in words", default: 200 },
        language: { type: "string", description: "Output language", default: "same as input" },
        execution_mode: { type: "string", enum: ["online", "offline"], default: "online" }
      }
    }
  },
  "text-generator": {
    description: "Generate text using OpenAI GPT-4o",
    parameters: {
      required: {
        prompt: { type: "string", description: "Prompt for text generation" }
      },
      optional: {
        model: { type: "string", enum: ["gpt-4o", "gpt-4o-mini", "gpt-4-turbo"], default: "gpt-4o" },
        temperature: { type: "number", minimum: 0, maximum: 2, default: 0.7 },
        max_tokens: { type: "integer", default: 1000 },
        system_prompt: { type: "string", description: "System prompt for context" },
        execution_mode: { type: "string", enum: ["online", "offline"], default: "online" }
      }
    }
  },
  "code-generator": {
    description: "Generate code using OpenAI GPT-4o",
    parameters: {
      required: {
        prompt: { type: "string", description: "Description of code to generate" }
      },
      optional: {
        language: { type: "string", description: "Programming language", default: "python" },
        framework: { type: "string", description: "Framework or library context" },
        context: { type: "string", description: "Additional context or existing code" },
        execution_mode: { type: "string", enum: ["online", "offline"], default: "online" }
      }
    }
  },
  "youtube-searcher": {
    description: "Search YouTube using the Data API v3",
    parameters: {
      required: {
        query: { type: "string", description: "Search query" }
      },
      optional: {
        type: { type: "string", enum: ["video", "channel", "playlist"], default: "video" },
        max_results: { type: "integer", minimum: 1, maximum: 50, default: 10 },
        order: { type: "string", enum: ["relevance", "date", "rating", "viewCount"], default: "relevance" },
        execution_mode: { type: "string", enum: ["online", "offline"], default: "online" }
      }
    }
  },
  "google-searcher": {
    description: "Search Google using SerpAPI",
    parameters: {
      required: {
        query: { type: "string", description: "Search query" }
      },
      optional: {
        num_results: { type: "integer", minimum: 1, maximum: 100, default: 10 },
        language: { type: "string", description: "Language code", default: "en" },
        country: { type: "string", description: "Country code", default: "us" },
        execution_mode: { type: "string", enum: ["online", "offline"], default: "online" }
      }
    }
  },
  "vector-store": {
    description: "Store, search, and manage vectors in Qdrant",
    parameters: {
      required: {
        action: { type: "string", enum: ["store", "search", "delete"], description: "Action to perform" }
      },
      optional: {
        collection: { type: "string", description: "Collection name", default: "default" },
        text: { type: "string", description: "Text to embed (for store)" },
        query: { type: "string", description: "Query for search" },
        id: { type: "string", description: "Vector ID (for delete)" },
        top_k: { type: "integer", description: "Results to return", default: 5 },
        metadata: { type: "object", description: "Additional metadata" },
        execution_mode: { type: "string", enum: ["online", "offline"], default: "online" }
      }
    }
  },
  "image-ocr": {
    description: "Extract text from images using Mistral Pixtral",
    parameters: {
      required: {
        image_url: { type: "string", description: "URL of the image to analyze" }
      },
      optional: {
        language: { type: "string", description: "Expected text language", default: "auto-detect" },
        output_format: { type: "string", enum: ["text", "structured"], default: "text" },
        execution_mode: { type: "string", enum: ["online", "offline"], default: "online" }
      }
    }
  },
  "llm-summarizer": {
    description: "Summarize with multi-provider support (Anthropic, OpenAI, Mistral)",
    parameters: {
      required: {
        text: { type: "string", description: "Text to summarize" }
      },
      optional: {
        provider: { type: "string", enum: ["anthropic", "openai", "mistral"], default: "anthropic" },
        format: { type: "string", enum: ["bullet-points", "paragraph", "executive-summary"], default: "paragraph" },
        max_length: { type: "integer", description: "Max summary length" },
        language: { type: "string", description: "Output language", default: "same as input" },
        execution_mode: { type: "string", enum: ["online", "offline"], default: "online" }
      }
    }
  },
  "text-classifier": {
    description: "Classify text into categories using OpenAI GPT-4o-mini",
    parameters: {
      required: {
        text: { type: "string", description: "Text to classify" },
        categories: { type: "array", items: "string", description: "Category labels" }
      },
      optional: {
        multi_label: { type: "boolean", description: "Allow multiple categories", default: false },
        execution_mode: { type: "string", enum: ["online", "offline"], default: "online" }
      }
    }
  }
};

// Build registry from active workflows
const workflows = $input.first().json.data || [];

// Filter active workflows starting with 'MCP -' (excluding this registry)
const mcpWorkflows = workflows.filter(w => 
  w.active && 
  w.name.startsWith('MCP -') && 
  w.name !== 'MCP - Registry'
);

// Extract webhook info from each workflow
const tools = {};

for (const workflow of mcpWorkflows) {
  const webhookNode = workflow.nodes?.find(n => n.type === 'n8n-nodes-base.webhook');

  if (webhookNode) {
    const webhookPath = webhookNode.parameters?.path || webhookNode.webhookId;
    const toolName = webhookPath; // Use webhook path as tool name
    const serviceName = workflow.name.replace('MCP - ', '').toLowerCase().replace(/[^a-z0-9]/g, '-');

    // Get schema if available
    const schema = toolSchemas[toolName] || toolSchemas[serviceName] || null;

    tools[toolName] = {
      name: workflow.name,
      workflow_id: workflow.id,
      endpoint: `/webhook/${webhookPath}`,
      webhook_url: `http://pi6.local:5678/webhook/${webhookPath}`,
      method: "POST",
      active: workflow.active,
      description: schema?.description || `MCP Tool: ${workflow.name}`,
      parameters: schema?.parameters || { required: {}, optional: {} }
    };
  }
}

const registry = {
  version: "2.0",
  updated_at: new Date().toISOString(),
  n8n: {
    host: "pi6.local",
    port: 5678,
    protocol: "http",
    webhook_base: "http://pi6.local:5678/webhook"
  },
  total_tools: Object.keys(tools).length,
  tools: tools
};

return { json: registry };
